// === ANALYSE GSC + SÉLECTION DU MOT-CLÉ ===

const gscData = $input.item.json;
const today = new Date();
const startOfYear = new Date(today.getFullYear(), 0, 1);
const dayOfYear = Math.floor((today - startOfYear) / 86400000);

// Liste de secours si GSC a peu de données
const fallbackKeywords = [
  { keyword: 'combien coûte un notaire', intention: 'tarifs et honoraires notaire', category: 'FAQ' },
  { keyword: 'délai succession notaire', intention: 'durée d une succession chez le notaire', category: 'FAQ' },
  { keyword: 'testament chez le notaire', intention: 'rédiger son testament chez un notaire', category: 'Service' },
  { keyword: 'notaire PACS', intention: 'signer un PACS chez le notaire', category: 'Service' },
  { keyword: 'donation enfant notaire', intention: 'faire une donation à ses enfants', category: 'Service' },
  { keyword: 'frais de notaire achat immobilier', intention: 'calculer les frais de notaire', category: 'FAQ' },
  { keyword: 'notaire divorce consentement mutuel', intention: 'divorce par acte notarié', category: 'Service' },
  { keyword: 'notaire Lyon', intention: 'trouver un notaire à Lyon', category: 'Local' },
  { keyword: 'notaire Marseille', intention: 'trouver un notaire à Marseille', category: 'Local' },
  { keyword: 'notaire Bordeaux', intention: 'trouver un notaire à Bordeaux', category: 'Local' },
  { keyword: 'notaire Toulouse', intention: 'trouver un notaire à Toulouse', category: 'Local' },
  { keyword: 'notaire Nantes', intention: 'trouver un notaire à Nantes', category: 'Local' },
  { keyword: 'notaire Lille', intention: 'trouver un notaire à Lille', category: 'Local' },
  { keyword: 'notaire Rennes', intention: 'trouver un notaire à Rennes', category: 'Local' },
  { keyword: 'notaire Nice', intention: 'trouver un notaire à Nice', category: 'Local' },
  { keyword: 'notaire Strasbourg', intention: 'trouver un notaire à Strasbourg', category: 'Local' },
  { keyword: 'notaire Montpellier', intention: 'trouver un notaire à Montpellier', category: 'Local' },
  { keyword: 'SCI notaire', intention: 'créer une SCI chez le notaire', category: 'Service' },
  { keyword: 'contrat de mariage notaire', intention: 'choisir son régime matrimonial', category: 'Service' },
  { keyword: 'notaire en ligne visio', intention: 'RDV notaire à distance', category: 'Service' },
  { keyword: 'héritage notaire', intention: 'comment se passe un héritage chez le notaire', category: 'Service' },
  { keyword: 'acte de vente notaire', intention: 'signature acte définitif notaire', category: 'Service' },
  { keyword: 'compromis de vente notaire', intention: 'signer compromis de vente', category: 'Service' },
  { keyword: 'prendre RDV notaire en ligne', intention: 'plateforme rdv notaire digital', category: 'Service' },
  { keyword: 'notaire succession Lyon', intention: 'notaire héritage succession à Lyon', category: 'Local' },
  { keyword: 'notaire immobilier Paris', intention: 'notaire spécialisé achat vente immobilier Paris', category: 'Local' },
  { keyword: 'notaire droit des sociétés', intention: 'notaire pour créer ou céder son entreprise', category: 'Service' },
  { keyword: 'notaire Grenoble', intention: 'trouver un notaire à Grenoble', category: 'Local' },
  { keyword: 'notaire Aix-en-Provence', intention: 'trouver un notaire à Aix-en-Provence', category: 'Local' },
  { keyword: 'notaire Toulon', intention: 'trouver un notaire à Toulon', category: 'Local' },
];

// Analyse des données GSC
const rows = gscData.rows || [];
let selectedKeyword = null;
let gscContext = '';
let source = 'fallback';

if (rows.length >= 3) {
  // Trier par opportunité : position 4-30 avec impressions > 1
  // (striking distance = presque en page 1, juste besoin de contenu de qualité)
  const opportunities = rows
    .filter(r => r.position >= 4 && r.position <= 30 && r.impressions >= 2)
    .sort((a, b) => {
      // Score = impressions × (31 - position) — plus impressions et plus proche du top, meilleur
      const scoreA = a.impressions * (31 - a.position);
      const scoreB = b.impressions * (31 - b.position);
      return scoreB - scoreA;
    });

  if (opportunities.length > 0) {
    const best = opportunities[dayOfYear % opportunities.length];
    selectedKeyword = {
      keyword: best.keys[0],
      intention: `améliorer le ranking sur "${best.keys[0]}"`,
      category: 'FAQ',
      gsc_position: Math.round(best.position * 10) / 10,
      gsc_impressions: best.impressions,
      gsc_clicks: best.clicks,
      gsc_ctr: Math.round(best.ctr * 1000) / 10,
    };
    source = 'gsc';
    gscContext = `\n\nDonnées Google Search Console réelles pour ce mot-clé :\n- Position actuelle : ${selectedKeyword.gsc_position} (objectif : top 3)\n- Impressions / 7j : ${selectedKeyword.gsc_impressions}\n- Clics / 7j : ${selectedKeyword.gsc_clicks}\n- CTR : ${selectedKeyword.gsc_ctr}%\nCe mot-clé est en striking distance — du contenu de qualité peut le faire passer en page 1.`;
  }
}

// Fallback si GSC ne donne pas assez de données (site récent)
if (!selectedKeyword) {
  const fb = fallbackKeywords[dayOfYear % fallbackKeywords.length];
  selectedKeyword = { ...fb, gsc_position: null, gsc_impressions: 0, gsc_clicks: 0, gsc_ctr: 0 };
}

return [{ json: { ...selectedKeyword, gscContext, source, date: today.toISOString().split('T')[0], dayOfYear } }];

const kw = $input.item.json;

const gscLine = kw.source === 'gsc'
  ? `

📊 DONNÉES GOOGLE SEARCH CONSOLE RÉELLES :
- Position actuelle : ${kw.gsc_position} → objectif top 3
- Impressions (7j) : ${kw.gsc_impressions}
- Clics (7j) : ${kw.gsc_clicks}
- CTR : ${kw.gsc_ctr}%
Google montre déjà ce site pour ce mot-clé — un article de qualité peut le faire passer en page 1.`
  : '';

const prompt = `Tu es un expert SEO spécialisé en droit notarial français, rédacteur senior pour Notaires.io.

Notaires.io est une plateforme digitale qui permet aux particuliers de trouver le bon notaire en 3 questions et prendre rendez-vous en visio ou au cabinet. 1er RDV offert. 17 000+ notaires référencés en France.${gscLine}

Génère un article SEO complet en français ciblant :
- Mot-clé principal : ${kw.keyword}
- Intention de recherche : ${kw.intention}
- Catégorie : ${kw.category}

Réponds UNIQUEMENT avec un objet JSON valide (sans markdown ni texte autour) :
{
  "meta_title": "titre <title>, 55-60 caractères, mot-clé en début",
  "meta_description": "meta desc 140-155 car avec appel à l'action clair",
  "h1": "titre H1 engageant et naturel",
  "slug": "slug-url-kebab-sans-accents-ni-caracteres-speciaux",
  "excerpt": "résumé 120-150 mots accrocheur, mot-clé dans les 50 premiers mots",
  "intro": "intro 80-100 mots, pose le problème et annonce la réponse",
  "content_html": "article HTML complet avec <h2>, <h3>, <p>, <ul><li>, <strong> — 1300 à 1700 mots",
  "faq": [{ "q": "question naturelle posée sur Google", "r": "réponse 60-80 mots, précise et actionnable" }],
  "category": "une de : Succession, Immobilier, Mariage, Famille, Donation, Guide, FAQ, Local",
  "reading_time": 6
}

Règles impératives :
- 4 à 6 sections H2 dans content_html
- 3 à 5 questions FAQ
- Ton expert mais accessible, jamais jargonneux sans explication
- Mentionner Notaires.io naturellement comme solution (sans forcer)
- Le slug ne doit pas déjà exister : évite ces slugs courants (succession, immobilier, mariage, testament, pacs, frais-notaire)`;

const body = JSON.stringify({
  model: 'claude-opus-4-7',
  max_tokens: 4096,
  messages: [{ role: 'user', content: prompt }]
});

return [{ json: { body, keyword: kw } }];

const response = $input.item.json;
const kw = $('🧠 Construire prompt Claude').item.json.keyword;

let rawText;
try {
  rawText = response.content[0].text;
} catch(e) {
  throw new Error('Réponse Claude illisible: ' + JSON.stringify(response).substring(0, 200));
}

let art;
try {
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  art = JSON.parse(cleaned);
} catch(e) {
  throw new Error('JSON invalide dans réponse Claude: ' + rawText.substring(0, 400));
}

// Slugifier proprement (précaution)
const slug = (art.slug || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9-]/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '');

const article = {
  slug,
  title: art.h1 || art.meta_title || kw.keyword,
  meta_title: art.meta_title || null,
  meta_description: art.meta_description || null,
  excerpt: art.excerpt || null,
  h1: art.h1 || null,
  intro: art.intro || null,
  content_html: art.content_html || '',
  faq_json: art.faq || null,
  category: art.category || kw.category || 'Guide',
  keyword: kw.keyword,
  keyword_type: kw.source || 'fallback',
  reading_time: art.reading_time || 6,
  published: true,
};

return [{ json: { article, keyword: kw } }];
